#!/usr/bin/env bash
# Run the relief window checker on every window generated by windows.sh (prompt 06).
#   tools/worldscan/checkrelief.sh <tag> [baseline-tag]    baseline-tag: the prompt 05 run to compare the dune columns with (default c08)
# Output: ${OUT:-docs/relief}/<tag>_<name>_s<seed>_check.json (window checker), ${OUT:-docs/relief}/<tag>_<name>_s<seed>.png (render of the generated heights)
set -e
ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"; cd "$ROOT"
TAG=$1; BASE=${2:-c08}; mkdir -p build/worldscan "${OUT:-docs/relief}"
CONT=src/main/resources/data/islandcraft_dunesofarrakis/arrakis/continents.json
grep -v '^#' tools/worldscan/windows.tsv | while IFS=$'\t' read -r name seed cx cz note; do
  [ -z "$name" ] && continue
  [[ -n "$ONLY" && ! "$name" =~ $ONLY ]] && continue
  [[ -n "$SKIP" && "$name" =~ $SKIP ]] && continue
  x0=$(( (cx - 512) / 16 * 16 )); z0=$(( (cz - 512) / 16 * 16 ))
  [ $(( (cx - 512) % 16 )) -lt 0 ] && x0=$(( x0 - 16 )); [ $(( (cz - 512) % 16 )) -lt 0 ] && z0=$(( z0 - 16 ))
  W="${TAG}_${name}_s${seed}"; R="run-server/$W/dimensions/islandcraft_dunesofarrakis/arrakis/region"
  M="build/worldscan/cmask_${name}_s${seed}.bin"; ./tools/worldscan/relief.sh $CONT mask $seed $x0 $z0 1024 "$M" >/dev/null
  RM="build/worldscan/rockmap_${name}_s${seed}.i16"; ./tools/worldscan/relief.sh $CONT rockmap $seed $x0 $z0 1024 "$RM" >/dev/null
  H="build/worldscan/heights_${W}.i16"; EXTRA="--save $H"
  B="build/worldscan/heights_${BASE}_${name}_s${seed}.i16"; [ -f "$B" ] && EXTRA="$EXTRA --baseline $B"
  echo "=== $W (x0 $x0 z0 $z0)"
  node tools/worldscan/windowcheck_relief.js "$R" "$M" "$RM" $x0 $z0 1024 "${OUT:-docs/relief}/${W}_check" $EXTRA
  node tools/worldscan/render.js "$R" "${OUT:-docs/relief}/${W}" $x0 $z0 1024 --scale 1 | grep -E "^height above|^chunk seams|^wrote" | cut -c1-210
done
